import type { Pagefind, SearchResult } from './types'

/** Generated by `pagefind --site out` after `next build`; absent while running `next dev`. */
const PAGEFIND_URL = '/pagefind/pagefind.js'
const MAX_RESULTS = 20

let pagefind: Promise<Pagefind> | undefined

function loadPagefind(): Promise<Pagefind> {
  pagefind ??= import(/* webpackIgnore: true */ /* turbopackIgnore: true */ PAGEFIND_URL)
  return pagefind
}

/**
 * Pagefind picks the index matching `<html lang>`, so results are already limited to the current locale.
 * Throws when the index is unavailable.
 */
export async function searchSite(term: string, filters: Record<string, string>): Promise<SearchResult[]> {
  const api = await loadPagefind()
  const search = await api.search(term || null, { filters })
  const results = await Promise.all(
    search.results.slice(0, MAX_RESULTS).map(async (result) => {
      const data = await result.data()
      return {
        id: result.id,
        url: data.url,
        title: data.meta.title ?? data.url,
        excerpt: data.excerpt,
        category: data.meta.category,
        description: data.meta.description,
        difficulty: data.meta.difficulty,
        isCategory: data.meta.kind === 'category',
      }
    }),
  )
  return results
}
